class Solution {
    public int pathsWithObstacles(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[] dp = new int[n];                   // dp[j] = paths into (current row, j)
        dp[0] = grid[0][0] == 1 ? 0 : 1;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) dp[j] = 0;          // blocked: no paths in
                else if (j > 0) dp[j] += dp[j - 1];      // above (old dp[j]) + left
            }
        }
        return dp[n - 1];
    }
}

